<script setup lang="ts">
import {ref,computed,watch} from 'vue'
import {useStudio,id,state,states} from '../studioContext'
import EntityActions from '../EntityActions.vue'
import ReviewUnit from '../ReviewUnit.vue'
import ReviewBadge from '../ReviewBadge.vue'
import AppIcon from '../AppIcon.vue'
import SmartEditButton from '../SmartEditButton.vue'
import SmartEditBatch from '../SmartEditBatch.vue'
import RegionPicker from '../RegionPicker.vue'
import Portrait from '../Portrait.vue'
import ExperienceSettings from '../ExperienceSettings.vue'
import {narrativeText} from '../narrative'
const s=useStudio(),selected=ref('');const intent=computed(()=>s.rec('intent','main')),plots=computed(()=>s.entries('plot')),plot=computed(()=>plots.value.find((r:any)=>r.id===selected.value)||plots.value[0])
const audience=['博物馆普通观众','学生','文化爱好者'],tones=['克制、生动','通俗易懂','戏剧化']
function add(){const r=s.add('plot',{title:'新剧情',goal:'',body:'',connection:'',characterIds:[],clueIds:[],region:null});selected.value=r.id}
function addClue(){if(!plot.value)return;const r=s.add('clue',{name:'新叙事线索',summary:'',content:'',type:'narrative',parentId:'narrative',plotIds:[plot.value.id],characterIds:plot.value.draft.characterIds,units:[{id:id(),text:'',kind:'event',category:'fiction',rationale:'',speakerId:'',references:[]}]});plot.value.draft.clueIds.push(r.id);s.navigate('clues','clue:'+r.id)}
watch(()=>s.focus.value,(v:string)=>{if(v.startsWith('plot:'))selected.value=v.split(':')[1]},{immediate:true})
</script>
<template><ReviewUnit unit-id="outline:main" label="确认整个大纲"/><div class="outline-layout"><article class="intent-panel" data-entity-key="intent:main"><div class="rail-heading"><h2>创作方向</h2><SmartEditButton kind="intent" :item-ids="['main']" label="创作方向"/></div><label>你想怎样讲这幅画的故事？<textarea rows="5" v-model="intent.draft.brief" placeholder="可留空，生成时根据资料给出默认方向"/></label><details><summary>主题、历史框架与高级设置（自动补齐）</summary><div class="compact-grid"><label>主题<input v-model="intent.draft.theme"></label><label>故事目标<textarea v-model="intent.draft.goal"/></label><label>目标观众<select :value="audience.includes(intent.draft.audience)?intent.draft.audience:'custom'" @change="intent.draft.audience=($event.target as HTMLSelectElement).value==='custom'?'':($event.target as HTMLSelectElement).value"><option v-for="a in audience">{{a}}</option><option value="custom">自定义</option></select><input v-if="!audience.includes(intent.draft.audience)" v-model="intent.draft.audience" placeholder="输入目标观众"></label><label>叙述语气<select :value="tones.includes(intent.draft.tone)?intent.draft.tone:'custom'" @change="intent.draft.tone=($event.target as HTMLSelectElement).value==='custom'?'':($event.target as HTMLSelectElement).value"><option v-for="t in tones">{{t}}</option><option value="custom">自定义</option></select><input v-if="!tones.includes(intent.draft.tone)" v-model="intent.draft.tone" placeholder="输入语气"></label></div><div class="boundary-lists"><details open v-for="(label,k) in {framework:'历史框架',fiction:'虚构内容',forbidden:'禁止内容'}"><summary>{{label}} | {{intent.draft[k].length}} 项</summary><small v-if="k==='framework'">基于你提供的可靠历史材料，在剧本创作中不可改动的框架。</small><div class="list-edit" v-for="(_,i) in intent.draft[k]"><textarea v-model="intent.draft[k][i]"/><button @click="intent.draft[k].splice(i,1)">删除</button></div><button @click="intent.draft[k].push('')">＋ 添加一项</button></details></div><label>初次生成剧情数<input type="number" min="1" max="12" v-model.number="intent.draft.plotCount"></label></details><EntityActions :record="intent"/><ExperienceSettings/></article>
<div><article :data-entity-key="plot?'plot:'+plot.id:undefined"><div class="rail-heading"><h2>剧情</h2><button @click="add">＋ 剧情</button></div><div class="plot-strip"><button v-for="r in plots" :class="{selected:r.id===plot?.id}" @click="s.selectEntity('plot',r.id)"><b>{{r.draft.title}}</b></button></div><SmartEditBatch kind="plot" :rows="plots" label="剧情"/><template v-if="plot"><fieldset :disabled="s.locked('plot',plot.id)"><div class="detail-title"><h3>{{plot.draft.title}}</h3><SmartEditButton kind="plot" :item-ids="[plot.id]" :label="plot.draft.title"/></div><label>剧情标题<input v-model="plot.draft.title"></label><label>剧情目标<textarea v-model="plot.draft.goal"/></label><label>具体发展<textarea rows="6" v-model="plot.draft.body"/></label><label>前后关联<textarea v-model="plot.draft.connection"/></label><div class="chip-choices"><label v-for="c in s.castEntries()"><input type="checkbox" :value="c.id" v-model="plot.draft.characterIds">{{c.draft.name}}</label></div><RegionPicker :image="s.p.value.image" v-model="plot.draft.region"/><Portrait v-if="plot.draft.region" :url="s.p.value.image" :box="plot.draft.region"/><fieldset :disabled="s.locked('plot',plot.id,'clueIds')"><h3>子叙事线索</h3><small>每条是一小段情节，只属于当前剧情。</small><div class="plot-child-clue" v-for="c in s.entries('clue').filter((r:any)=>r.draft.type==='narrative'&&r.draft.plotIds?.length===1&&r.draft.plotIds[0]===plot.id)"><div><b>{{c.draft.name}}</b><p>{{narrativeText(c.draft)}}</p></div><button @click="s.navigate('clues','clue:'+c.id)">编辑</button></div><div class="actions"><button :disabled="s.busy.value||s.generating.value" title="生成期间不能重复提交任务" @click="s.generate('plot_clues',plot.id)"><AppIcon name="ai" :size="14"/>生成子叙事线索</button><button @click="addClue">＋ 手动添加</button></div><small>生成结果追加为草稿，不改写剧情，不覆盖已有线索。</small></fieldset><EntityActions :record="plot"/><div class="actions"><button :disabled="s.busy.value||s.generating.value" title="生成期间不能重复提交任务" @click="s.generate('plot',plot.id)"><AppIcon name="ai" :size="14"/>重生成本剧情及线索</button><button @click="s.remove(plot)">删除剧情</button></div></fieldset></template><div v-else class="empty">使用页首生成剧本大纲，或手动添加。</div></article></div></div></template>
